description:
Design a circuit that calculates the even parity of an 8-bit input. The module takes an 8-bit input `data_in` and produces a single-bit output `parity_out` that indicates whether the number of high bits (1s) in the input is even or odd. The function computes the parity by performing a series of XOR operations on each bit of the input, ultimately resulting in an output of 1 if there is an odd count of 1s (odd parity) and 0 if the count is even (even parity).
module top_module(
data_in    , 
parity_out   
);

code:
module top_module(
data_in    , 
parity_out   
);output  parity_out ;
input [7:0] data_in ; 

wire parity_out ; 

function parity;
  input [31:0] data; 
  begin
    parity =  (data_in[0] ^ data_in[1]) ^  
              (data_in[2] ^ data_in[3]) ^ 
              (data_in[4] ^ data_in[5]) ^  
              (data_in[6] ^ data_in[7]);
  end 
endfunction 


assign parity_out = parity(data_in);

endmodule

