description:
Design a 32-bit binary counter that increments its value with each positive clock edge. The counter resets to zero when the reset signal is asserted, and its current count value is continuously available on the output y.
module top_module(
	input wire clk,
	input wire reset,
	output wire [31:0]y
    );

code:
module top_module(
	input wire clk,
	input wire reset,
	output wire [31:0]y
    );reg[31:0]q;
	always@(posedge clk) begin
		if( reset )  begin 
			q= 32'd0;
		end else begin
			q= q + 32'd1; 
		end
	end 
	assign y= q;
endmodule

