    reg [35:0] memory [0:1023]; // Example memory depth of 1024 (10-bit address space)

    always @(posedge CLK) begin
        if (WE) begin
            memory[ADDR] <= DATAIN; // Write operation
        end
    end

    always @(posedge CLK) begin
        if (OE) begin
            DATAOUT <= memory[ADDR]; // Read operation
        end
    end

endmodule

