description:
Design a 4-to-2 priority encoder. The circuit takes a 4-bit input and outputs a 2-bit code representing the highest-order active input bit. If multiple bits are high, only the index of the highest active input is encoded in the output. The design ensures that the output is updated whenever the input changes.
module top_module(
	input  [3 : 0] code_in,
       	output reg	[1 : 0] code_out
);

code:
module top_module(
	input  [3 : 0] code_in,
       	output reg	[1 : 0] code_out
);reg flag;
	integer i;

	always@(code_in)
	begin


		flag = 0;
		for(i = 0; i <= 3; i = i + 1) begin
			if(code_in[i] && flag == 0) begin
				code_out = i;
				flag = 1;
			end	
		end

	end

endmodule

