    end
    else if(sel2 == 0 && sel1 == 1 && sel0 == 0) begin
        stage1_out[48] = 1'b1;
    end
end

always @(posedge clk) begin
    stage2_out <= stage1_out;
end

assign out = stage2_out;

endmodule

