    input rst,
    input [3:0] bin_in,
    output [3:0] dec_out,
    output valid_out
);reg [3:0] dec_out_reg;
reg valid_out_reg;

always @(posedge clk) begin
    if (rst) begin
        dec_out_reg <= 0;
        valid_out_reg <= 0;
    end
    else begin
        case (bin_in)
            4'b0000: dec_out_reg <= 4'b0000;
