module counter8bit_down (
    input clk,
    input rst,
    input en,
    output [7:0] q
);

    reg [7:0] q_reg;

    always @(posedge clk or posedge rst) begin
        if (rst)
            q_reg <= 8'b11111111;
        else if (en)
            q_reg <= q_reg - 1;
    end

    assign q = q_reg;

endmodule

